<?php
namespace Modules\Ran\Services;use DomainException;use Illuminate\Support\Facades\DB;use Modules\Ran\Entities\{Sale,SaleLine,SaleReturn,SaleReturnLine,StockLot};use Modules\Ran\Integrations\{CustomerIntegrationService,FinanceIntegrationService};use Modules\Ran\Support\RanContext;
class SaleReturnService{public function __construct(private NumberSequenceService $numbers,private InventoryService $inventory,private CustomerIntegrationService $customers,private FinanceIntegrationService $finance,private AuditService $audit){}public function createAndPost(array $d):SaleReturn{return DB::transaction(function()use($d){$sale=Sale::query()->findOrFail($d['sale_id']);if($sale->status!=='posted')throw new DomainException('Only posted sales can be returned.');$total=collect($d['lines'])->sum(fn($l)=>(float)$l['amount']);$r=SaleReturn::create(array_merge(RanContext::scope(['location_id'=>$sale->location_id,'store_id'=>$sale->store_id]),['return_no'=>$this->numbers->next('sale_return'),'return_date'=>$d['return_date'],'sale_id'=>$sale->id,'customer_contact_id'=>$sale->customer_contact_id,'status'=>'posted','total_amount'=>$total,'reason'=>$d['reason'],'posted_by'=>RanContext::userId(),'posted_at'=>now()]));foreach($d['lines'] as $l){$sl=SaleLine::query()->where('sale_id',$sale->id)->findOrFail($l['sale_line_id']);$already=(float)SaleReturnLine::query()->where('sale_line_id',$sl->id)->whereHas('saleReturn',fn($q)=>$q->where('status','posted'))->sum('quantity');if($already+(float)$l['quantity']>(float)$sl->quantity+0.0001)throw new DomainException('Return quantity exceeds the remaining sold quantity for '.$sl->description);if((float)$l['amount']>(float)$sl->line_total+0.0001)throw new DomainException('Return amount exceeds the sold line value.');$rl=SaleReturnLine::create(array_merge(RanContext::scope(['location_id'=>$sale->location_id,'store_id'=>$sale->store_id]),$l,['sale_return_id'=>$r->id,'item_id'=>$sl->item_id,'stock_lot_id'=>$sl->stock_lot_id]));if($l['condition']==='good')$this->inventory->receive(['location_id'=>$sale->location_id,'store_id'=>$sale->store_id,'item_id'=>$sl->item_id,'quantity'=>$l['quantity'],'gross_weight'=>$l['weight'],'net_weight'=>$l['weight'],'unit_cost'=>$sl->cost_amount/max((float)$sl->quantity,0.0001),'total_cost'=>($sl->cost_amount/max((float)$sl->quantity,0.0001))*(float)$l['quantity'],'sale_price'=>$sl->unit_price,'received_on'=>$r->return_date,'source_type'=>'sale_return','source_id'=>$r->id,'reference_no'=>$r->return_no]);}$this->finance->postReturn($r);if($r->customer_contact_id)$this->customers->credit((int)$r->customer_contact_id,$total,(string)$r->return_date,"Ran Return {$r->return_no}");$this->audit->record('sale_return_posted',$r);return $r->load('lines');});}}
